<template>
  <template v-if="page==='tasks'"><StatCards :items="stats"/><section class="panel"><div class="panel-title"><div><h2>待处理检测任务</h2><p>任务由系统管理员按照所属网格进行指派。</p></div><button class="secondary" @click="load">刷新</button></div><el-table :data="tasks" stripe><el-table-column prop="feedbackNo" label="任务编号" min-width="170"/><el-table-column prop="province" label="省份"/><el-table-column prop="city" label="城市"/><el-table-column prop="address" label="观测地址" min-width="200"/><el-table-column label="预估AQI"><template #default="s"><AqiBadge :value="s.row.estimate"/></template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><button class="table-action" @click="selected=s.row">选择录入</button></template></el-table-column></el-table></section></template>
  <section v-else-if="page==='measure'" class="content-grid"><article class="panel form-panel"><h2>实测数据录入</h2><label>检测任务<select v-model="selectedId"><option v-for="item in pending" :key="item.id" :value="item.id">{{item.feedbackNo}} · {{item.city}} · {{item.address}}</option></select></label><div class="form-grid"><label>SO2 二氧化硫<select v-model="form.so2"><option v-for="item in levels">{{item}}</option></select></label><label>CO 一氧化碳<select v-model="form.co"><option v-for="item in levels">{{item}}</option></select></label><label>PM2.5 颗粒物<select v-model="form.pm25"><option v-for="item in levels">{{item}}</option></select></label></div><button class="primary compact" @click="submit">提交实测结果</button></article><article class="panel result-panel"><span>系统自动计算最终AQI</span><AqiBadge :value="finalLevel"/><strong>{{finalLevel}}</strong><p>AQI = MAX（SO2，CO，PM2.5）</p><small>取三项污染物中等级最高的一项作为最终结果</small></article></section>
  <template v-else><StatCards :items="stats"/><section class="content-grid"><article class="panel"><h2>当前工作状态</h2><div class="status-line"><i class="fa-solid fa-circle-check"></i><div><strong>{{session.workStatus}}</strong><span>{{session.province}} · {{session.city}}</span></div></div><p>系统根据所属城市优先分配本地任务；无可用人员时可由管理员发起异地支援。</p></article><article class="panel"><h2>最近完成记录</h2><ul class="simple-list"><li v-for="item in done.slice(0,5)" :key="item.id"><span>{{item.feedbackNo}} · {{item.city}}</span><AqiBadge :value="item.finalAqi"/></li></ul></article></section></template>
</template>
<script setup>
import {computed,onMounted,reactive,ref,watch} from 'vue'; import {ElMessage} from 'element-plus'; import http from '../api/http'; import AqiBadge from '../components/AqiBadge.vue'; import StatCards from '../components/StatCards.vue'; const props=defineProps({page:String,session:Object}); const tasks=ref([]),selectedId=ref(null); const levels=['优','良','轻度污染','中度污染','重度污染','严重污染']; const form=reactive({so2:'优',co:'优',pm25:'优'}); const pending=computed(()=>tasks.value.filter(x=>x.status==='已指派')); const done=computed(()=>tasks.value.filter(x=>x.status==='已完成')); const finalLevel=computed(()=>levels[Math.max(levels.indexOf(form.so2),levels.indexOf(form.co),levels.indexOf(form.pm25))]); const stats=computed(()=>[{label:'任务总数',value:tasks.value.length,icon:'fa-solid fa-list-check'},{label:'待检测',value:pending.value.length,icon:'fa-solid fa-hourglass-half'},{label:'已完成',value:done.value.length,icon:'fa-solid fa-circle-check'},{label:'工作状态',value:props.session.workStatus,icon:'fa-solid fa-user-clock'}]); const selected=computed({get:()=>tasks.value.find(x=>x.id===selectedId.value),set:v=>selectedId.value=v.id}); async function load(){tasks.value=(await http.get('/feedbacks',{params:{workerId:props.session.id}})).data;if(!selectedId.value&&pending.value[0])selectedId.value=pending.value[0].id} async function submit(){if(!selectedId.value)return ElMessage.warning('当前没有可录入任务');await http.post('/measurements',{feedbackId:selectedId.value,workerId:props.session.id,...form});ElMessage.success('实测数据已入库');selectedId.value=null;await load()} onMounted(load)
</script>
